from collections import deque

def minimum_knight_moves(x: int, y: int) -> int:
    """
    Find minimum moves for a knight to reach (x,y) from (0,0).
    Uses BFS to guarantee shortest path on infinite chessboard.
    """
    directions = [(2, 1), (2, -1), (-2, 1), (-2, -1),
                  (1, 2), (1, -2), (-1, 2), (-1, -2)]

    # Initialize BFS queue with (x, y, moves) and visited set
    queue = deque([(0, 0, 0)])
    visited = {(0, 0)}

    while queue:
        cx, cy, moves = queue.popleft()

        # Check if we reached the target
        if (cx, cy) == (x, y):
            return moves

        # Explore all 8 possible knight moves
        for dx, dy in directions:
            nx, ny = cx + dx, cy + dy

            if (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, moves + 1))

    return -1  # Target not reachable (shouldn't happen per problem)
